import { query } from './query';
test('rejects unsupported columns', () => { expect(() => query('id; DROP TABLE accounts', 'x')).toThrow('Unsupported column'); });
test('keeps the value out of the SQL text', () => { expect(query('email', "a' OR '1'='1")).toEqual({ text: 'SELECT id FROM accounts WHERE email = $1', values: ["a' OR '1'='1"] }); });

